//! Balances — and the conversion that has to happen at the boundary, not in somebody's head.
//!
//! # A person types what the statement prints
//!
//! That is the whole design constraint. A card statement says `2,431.07` and means you OWE it; a
//! chequing statement says `1,200.00` and means you HAVE it. The analysis needs both SIGNED by their
//! contribution to net worth, so something must convert — and asking a person to pre-negate a card
//! balance is asking them to get it wrong. They will type what they are looking at.
//!
//! So [`set_printed`] takes the printed figure and the account's KIND, and converts. Which means it
//! cannot store a balance for an account the registry has never heard of: without the kind, the sign
//! is not merely unknown, it is unknowable, and storing the number unconverted would put a debt into
//! net worth as an asset. The refusal is principled rather than fussy.
//!
//! # History is kept, and the LATEST is what gets used
//!
//! `position` rolls a balance forward with the transactions after it, so the most recent balance is
//! the one with the least rolling to do and therefore the least room for drift. Older ones are kept
//! rather than overwritten — a balance is an observation, and a store that forgets observations
//! cannot answer why a figure changed.

pub use from_printed::from_printed;
pub use latest_for::latest_for;
pub use latest_each::latest_each;
pub use record::record;
pub use without_balance::without_balance;
pub use to_json::to_json;
pub use from_json::from_json;
pub use from_periods::from_periods;
pub use prefer_observed::prefer_observed;

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;
    use crate::account::{Account, Kind};
    use crate::position::AccountBalance;
    use crate::reconcile::StatementPeriod;

    // SYNTHETIC FIXTURES ONLY.
    fn period(account: &str, to: &str, closing: i64) -> StatementPeriod {
        crate::reconcile::usd_period(account, "2026-06-01", to, 0, closing)
    }

    #[test]
    fn a_statements_closing_figure_becomes_a_balance_at_the_period_end() {
        let out = from_periods(&[period("chase-checking", "2026-06-20", 40_000)]);
        assert_eq!(out.len(), 1);
        assert_eq!(out[0].as_of, "2026-06-20", "the balance is observed when the period CLOSED");
        assert_eq!(out[0].balance.minor, 40_000);
    }

    #[test]
    fn a_balance_a_person_typed_beats_the_one_derived_for_that_same_day() {
        let derived = from_periods(&[period("chase-checking", "2026-06-20", 40_000)]);
        // They looked at the account and it said 385.12 — the export was stale, or a fee landed after.
        let stored = vec![AccountBalance {
            account: "chase-checking".to_string(),
            as_of: "2026-06-20".to_string(),
            balance: usd(38_512),
        }];
        let out = prefer_observed(&stored, &derived);
        assert_eq!(out.len(), 1, "same account, same day is ONE observation, not two");
        assert_eq!(out[0].balance.minor, 38_512, "the correction must survive the derivation");
    }

    #[test]
    fn a_stored_balance_on_another_day_is_kept_alongside_the_derived_one() {
        let derived = from_periods(&[period("chase-checking", "2026-06-20", 40_000)]);
        let stored = vec![AccountBalance {
            account: "chase-checking".to_string(),
            as_of: "2026-07-02".to_string(),
            balance: usd(12_000),
        }];
        let out = prefer_observed(&stored, &derived);
        assert_eq!(out.len(), 2, "different days are different observations");
        assert_eq!(latest_for(&out, "chase-checking").unwrap().balance.minor, 12_000);
    }

    fn acct(id: &str, kind: Kind) -> Account {
        Account {
            id: id.into(),
            institution: id.into(),
            kind,
            currency: "USD".into(),
            credit_limit: None,
            apr_bps: None,
            minimum_payment: None,
            statement_day: None,
            note: None,
        }
    }

    #[test]
    fn a_card_balance_typed_as_printed_becomes_a_debt() {
        // THE WHOLE POINT. A person types 2431.07 because that is what they are looking at. Stored
        // unconverted it would be $2,431 of net worth in the wrong direction — a $4,862 error on one
        // account, and it would look entirely plausible.
        let b = from_printed("card", "2026-06-30", usd(243_107), Kind::Credit);
        assert_eq!(b.balance.minor, -243_107);
    }

    #[test]
    fn a_chequing_balance_typed_as_printed_is_left_alone() {
        assert_eq!(from_printed("checking", "2026-06-30", usd(120_000), Kind::Checking).balance.minor, 120_000);
    }

    #[test]
    fn an_overpaid_card_prints_negative_and_becomes_money_you_have() {
        // The rule holds in both directions rather than being a special case for the common one.
        assert_eq!(from_printed("card", "2026-06-30", usd(-5_000), Kind::Credit).balance.minor, 5_000);
    }

    #[test]
    fn the_latest_observation_is_the_one_used() {
        // position rolls forward from it, so the nearer the observation the less there is to get
        // wrong on top of it.
        let mut bs = Vec::new();
        record(&mut bs, from_printed("card", "2026-04-30", usd(300_000), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-06-30", usd(243_107), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-05-31", usd(280_000), Kind::Credit));
        assert_eq!(latest_for(&bs, "card").unwrap().as_of, "2026-06-30");
        assert_eq!(bs.len(), 3, "earlier observations are kept, not overwritten");
    }

    #[test]
    fn the_same_account_on_the_same_day_is_a_correction_not_a_second_observation() {
        let mut bs = Vec::new();
        record(&mut bs, from_printed("card", "2026-06-30", usd(999_999), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-06-30", usd(243_107), Kind::Credit));
        assert_eq!(bs.len(), 1);
        assert_eq!(bs[0].balance.minor, -243_107);
    }

    #[test]
    fn latest_each_gives_position_exactly_one_row_per_account() {
        let mut bs = Vec::new();
        record(&mut bs, from_printed("card", "2026-04-30", usd(300_000), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-06-30", usd(243_107), Kind::Credit));
        record(&mut bs, from_printed("checking", "2026-06-30", usd(120_000), Kind::Checking));
        let latest = latest_each(&bs);
        assert_eq!(latest.len(), 2);
        assert_eq!(latest.iter().find(|b| b.account == "card").unwrap().balance.minor, -243_107);
    }

    #[test]
    fn an_account_with_no_balance_is_named_rather_than_shown_as_zero() {
        let accounts = [acct("card", Kind::Credit), acct("checking", Kind::Checking)];
        let bs = vec![from_printed("card", "2026-06-30", usd(243_107), Kind::Credit)];
        assert_eq!(without_balance(&accounts, &bs), ["checking"]);
        assert!(without_balance(&accounts, &[]).len() == 2);
    }

    #[test]
    fn a_round_trip_keeps_the_sign_and_the_currency() {
        let mut bs = Vec::new();
        record(&mut bs, from_printed("card", "2026-06-30", usd(243_107), Kind::Credit));
        record(&mut bs, from_printed("checking", "2026-06-30", usd(120_000), Kind::Checking));
        let back = from_json(&to_json(&bs));
        assert_eq!(back, bs);
        assert_eq!(back[0].balance.minor, -243_107);
    }

    #[test]
    fn the_wire_shape_says_the_number_is_signed() {
        // A reader that took this for a printed figure would negate every card balance back to
        // wrong, so the key says which convention it is in.
        let bs = vec![from_printed("card", "2026-06-30", usd(243_107), Kind::Credit)];
        let v = to_json(&bs);
        assert!(v[0].get("signedMinor").is_some());
        assert!(v[0].get("printed").is_none());
        assert_eq!(v[0]["signedMinor"], -243_107);
    }

    #[test]
    fn rubbish_in_the_store_is_dropped_rather_than_defaulted() {
        let v = serde_json::json!([
            { "account": "ok", "asOf": "2026-06-30", "signedMinor": -1, "currency": "USD" },
            { "account": "no-date", "signedMinor": -1 },
            { "asOf": "2026-06-30", "signedMinor": -1 },
        ]);
        let back = from_json(&v);
        assert_eq!(back.len(), 1);
        assert_eq!(back[0].account, "ok");
    }
}
